import React from 'react';
import MainHeading from '../../Components/Heading/MainHeading';
import NavBar from '../../Components/NavBar/NavBar';
import big from "./Big Bang.png"
import "./home.css"


function Home() {
  return (
    <div className='bg-gray-900 h-screen  '>
      <NavBar/>
      <div className=" flex-col">
        <img src={big} alt="Big Bang" className='sm:w-max md:w-1/2 md:h-auto ' />
        <div className="">
          <h1 className=' text-white'>Big Bang</h1>
        </div>
      </div>
    
    </div>
  );
}

export default Home;
